parameters.jsCode:
// Parse Gemini response and extract article data
const response = $input.item.json;

try {
  // Get the text from Gemini response
  const text = response.candidates[0].content.parts[0].text;

  // Clean up: remove markdown code blocks if present
  let cleanText = text.replace(/```json\n?/g, '').replace(/```\n?/g, '').trim();

  // Parse JSON
  const article = JSON.parse(cleanText);

  // Validate
  if (!article.title || !article.content) {
    throw new Error('Missing title or content in Gemini response');
  }

  // Enhance content with affiliate box template
  const affiliateBox = `
<div class="pm-affiliate-box" style="background: linear-gradient(135deg, #f0fff4, #c6f6d5); border-left: 4px solid #38a169; padding: 20px; margin: 30px 0; border-radius: 8px;">
  <h3 style="color: #276749; margin-top: 0;">🛒 Recommended Tool</h3>
  <p>The single best investment for any serious plant parent is a high-quality <strong>soil moisture meter</strong>. It eliminates all guesswork and prevents both overwatering and underwatering — the #1 cause of plant death.</p>
  <a href="https://www.amazon.com/s?k=soil+moisture+meter+plants&tag=plantsmag-20" target="_blank" rel="noopener" style="display: inline-block; background: #FF9900; color: white; padding: 12px 24px; text-decoration: none; border-radius: 6px; font-weight: bold; margin-top: 10px;">🔍 Check Best Options on Amazon →</a>
</div>`;

  // Add affiliate box before last paragraph
  let content = article.content;
  const lastPIndex = content.lastIndexOf('<p>');
  if (lastPIndex > 0) {
    content = content.slice(0, lastPIndex) + affiliateBox + content.slice(lastPIndex);
  } else {
    content += affiliateBox;
  }

  return {
    title: article.title,
    meta_description: article.meta_description || '',
    content: content,
    topic: $('🌿 Select Random Topic').item.json.selectedTopic
  };

} catch (e) {
  throw new Error(`Failed to parse Gemini response: ${e.message}. Raw: ${JSON.stringify(response).slice(0, 500)}`);
}
